const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

module.exports = ui_filter_bar

async function ui_filter_bar (opts, invite) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    icons: iconject
  }

  const { io } = net(id)

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="ui-filter-bar">
      <button class="filter-btn icon-btn btn-filter"></button>
      <div class="filter-scroll-container">
        <button class="filter-item active">Loaders</button>
        <button class="filter-item">Check Box</button>
        <button class="filter-item">Toggle button</button>
        <button class="filter-item">Cards</button>
        <button class="filter-item">Buttons</button>
        <button class="filter-item">Input field</button>
        <button class="filter-item">My Saves</button>
      </div>
    </div>
  `

  const sheet = new CSSStyleSheet()
  shadow.adoptedStyleSheets = [sheet]

  const btn_filter = shadow.querySelector('.btn-filter')
  const scroll_container = shadow.querySelector('.filter-scroll-container')

  // -----------------------------------
  // Toggle Visibility Event Listener
  // -----------------------------------
  btn_filter.addEventListener('click', () => {
    scroll_container.classList.toggle('hidden')
  })

  await sdb.watch(onbatch)

  if (invite) io.accept(invite)

  return el

  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(path => drive.get(path).then(file => file.raw))
      )

      const handler = on[type] || (() => {})
      handler({ data })
    }
  }

  function inject ({ data }) {
    sheet.replaceSync(data[0])
  }

  function iconject ({ data }) {
    if (btn_filter) btn_filter.innerHTML = data[0] || ''
  }
}

function fallback_module () {
  return {
    api: fallback_instance,
    _: {
      net_helper: { $: '' }
    }
  }

  function fallback_instance () {
    return {
      _: {
        net_helper: { 0: '' },
        ui_filter_bar: {
          mapping: {
            style: 'style',
            icons: 'icons'
          }
        }
      },
      drive: {
        'icons/': {
          'filter.svg': { '$ref': 'filter.svg' }
        },
        'style/ui_filter_bar.css': {
          '$ref': 'ui_filter_bar.css'
        }
      }
    }
  }
}